"use client";

import { useMemo, useState } from "react";
import Image from "next/image";
import { backgrounds, brand } from "@/data/site";
import { SplitHeading } from "@/components/ui/SplitHeading";
import { Button } from "@/components/ui/Button";

/** Decorative QR-style pattern (not a scannable code): a real QR is generated by the backend later */
function PseudoQR({ seed }: { seed: string }) {
  const cells = useMemo(() => {
    let h = 2166136261;
    for (const c of seed || "DUNGEON") h = Math.imul(h ^ c.charCodeAt(0), 16777619);
    const out: boolean[] = [];
    for (let i = 0; i < 21 * 21; i++) {
      h = Math.imul(h ^ (h >>> 13), 1274126177);
      out.push((h >>> 0) % 100 < 48);
    }
    return out;
  }, [seed]);
  const finder = (x: number, y: number) => (
    <g key={`${x}${y}`}>
      <rect x={x} y={y} width="7" height="7" fill="currentColor" />
      <rect x={x + 1} y={y + 1} width="5" height="5" fill="var(--ticket-bg)" />
      <rect x={x + 2} y={y + 2} width="3" height="3" fill="currentColor" />
    </g>
  );
  const inFinder = (x: number, y: number) => (x < 8 && y < 8) || (x > 12 && y < 8) || (x < 8 && y > 12);
  return (
    <svg viewBox="0 0 21 21" className="qr" shapeRendering="crispEdges" aria-hidden>
      {cells.map((on, i) => {
        const x = i % 21;
        const y = Math.floor(i / 21);
        return on && !inFinder(x, y) ? <rect key={i} x={x} y={y} width="1" height="1" fill="currentColor" /> : null;
      })}
      {finder(0, 0)}
      {finder(14, 0)}
      {finder(0, 14)}
    </svg>
  );
}

export function FreePass() {
  const [name, setName] = useState("");
  const [phone, setPhone] = useState("");
  const [claimed, setClaimed] = useState(false);
  const passNo = useMemo(() => {
    let h = 7;
    for (const c of name + phone) h = (h * 31 + c.charCodeAt(0)) % 99991;
    return `DG-${String(h).padStart(5, "0")}`;
  }, [name, phone]);

  const submit = (e: React.FormEvent) => {
    e.preventDefault();
    if (!name.trim() || phone.replace(/\D/g, "").length < 10) return;
    setClaimed(true);
    // Backend later: POST /api/passes → save lead, send WhatsApp/SMS confirmation
  };

  return (
    <section id="pass" className="section pass">
      <div className="pass__bg" aria-hidden>
        <Image src={backgrounds.pass} alt="" fill sizes="100vw" />
      </div>
      <div className="pass__glow" aria-hidden />
      <div className="container pass__grid">
        <div className="pass__copy">
          <p className="eyebrow">Free Dungeon Pass</p>
          <SplitHeading className="h-xl" lines={["Your first", { text: "day is", className: "" }, { text: "on us", className: "gold-text" }]} />
          <p className="lead">Claim a free 1-day pass. Train in the Iron Pit, take a class, and finish in the steam room.</p>

          {!claimed ? (
            <form className="pass__form" onSubmit={submit}>
              <label>
                <span>Your name</span>
                <input value={name} onChange={(e) => setName(e.target.value)} placeholder="e.g. Arjun Sharma" required maxLength={28} />
              </label>
              <label>
                <span>Phone (WhatsApp)</span>
                <input
                  value={phone}
                  onChange={(e) => setPhone(e.target.value)}
                  placeholder="10-digit mobile"
                  inputMode="tel"
                  required
                  pattern="[0-9+\s\-]{10,15}"
                />
              </label>
              <Button label="Claim my free pass" type="submit" />
            </form>
          ) : (
            <div className="pass__done">
              <h3>Welcome to the Dungeon, {name.split(" ")[0]}.</h3>
              <p>Show this pass at the front desk. We&apos;ll also message you on WhatsApp at {phone}.</p>
              <button className="chip" onClick={() => setClaimed(false)} data-cursor="">
                Edit details
              </button>
            </div>
          )}
        </div>

        <div className={`ticket ${claimed ? "is-claimed" : ""}`} data-cursor="">
          <div className="ticket__main">
            <div className="ticket__top">
              <span className="ticket__brand">{brand.full}</span>
              <span className="ticket__type">1-Day Pass</span>
            </div>
            <div className="ticket__name">
              <small>Warrior</small>
              <strong>{name || "Your Name"}</strong>
            </div>
            <div className="ticket__meta">
              <div>
                <small>Pass No.</small>
                <b>{passNo}</b>
              </div>
              <div>
                <small>Access</small>
                <b>Gym + Spa</b>
              </div>
              <div>
                <small>Valid</small>
                <b>7 days</b>
              </div>
            </div>
          </div>
          <div className="ticket__stub">
            <PseudoQR seed={name + phone} />
            <small>Scan at gate</small>
          </div>
          <span className="ticket__stamp">Claimed</span>
        </div>
      </div>
    </section>
  );
}
